-- +goose Up
-- Module: Identity — docs/DATABASE.md §4, module group 1.
-- Tables: tenants (registry, outside tenant RLS), users, devices.
--
-- Conventions assumed here and by every later migration (§2): UUID identifiers are
-- UUIDv7 generated by the application, never by the database (§2.2); timestamps are
-- TIMESTAMPTZ (§2.5); every foreign key is ON DELETE RESTRICT (§2.7); every
-- tenant-scoped table has at least one index leading with tenant_id (§2.6).
--
-- Sprint 1 creates tables only. Row-level security policies and the FORCE RLS pin
-- (§2.11, §5) belong to Sprint 2; nothing here precludes them.

-- `tenants` — the registry root; every tenant_id in the schema anchors here.
-- No updated_at: registry rows are not device-synced and MVP has no plan changes (§2.5).
CREATE TABLE tenants (
    id         UUID        NOT NULL,
    name       TEXT        NOT NULL,
    plan       TEXT        NOT NULL DEFAULT 'free',
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT tenants_pkey PRIMARY KEY (id),
    CONSTRAINT tenants_plan_chk CHECK (plan IN ('free', 'standard', 'pro'))
);

-- `users` — cashier/owner accounts. `phone` is globally UNIQUE: POST /auth/login
-- carries no tenant discriminator, so the tenant arrives only inside the token.
-- Server-born table: created_at only, no updated_at (§2.5).
CREATE TABLE users (
    id            UUID        NOT NULL,
    tenant_id     UUID        NOT NULL,
    phone         TEXT        NOT NULL,
    password_hash TEXT        NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL,
    CONSTRAINT users_pkey PRIMARY KEY (id),
    CONSTRAINT users_phone_key UNIQUE (phone),
    CONSTRAINT users_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);

-- The 2.6 tenant-leading rule; the UNIQUE backing index serves the login lookup.
CREATE INDEX users_tenant_id_idx ON users (tenant_id);

-- `devices` — a phone bound to one cashier. Carries the offline-unlock credentials:
-- the PIN hash and the offline session expiry (valid 7+ days after bind).
-- Server-managed and mutable by the auth lifecycle, but not append-only, so it still
-- carries no updated_at: §2.5 places updated_at on exactly two tables (products,
-- fiado_accounts).
CREATE TABLE devices (
    id                          UUID        NOT NULL,
    tenant_id                   UUID        NOT NULL,
    user_id                     UUID        NOT NULL,
    pin_hash                    TEXT        NOT NULL,
    offline_session_valid_until TIMESTAMPTZ NOT NULL,
    created_at                  TIMESTAMPTZ NOT NULL,
    CONSTRAINT devices_pkey PRIMARY KEY (id),
    CONSTRAINT devices_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT,
    CONSTRAINT devices_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT
);

-- 2.6 tenant-leading rule; serves the bound-cashier lookup and covers both FK columns.
CREATE INDEX devices_tenant_id_user_id_idx ON devices (tenant_id, user_id);

-- +goose Down
-- Reverse dependency order: devices -> users -> tenants.
DROP TABLE IF EXISTS devices;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS tenants;
